head.script:
scwin.gBondYn;
scwin.vIMKT_ID;
scwin.vDepCd;
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();
        // fn_SetCode();

        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_2);
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        scwin.init();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26601.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    let vIBAS_YY = $c.stf.getQuery(frame.srcUrl, "BAS_YY");
    let vIBAS_ACNTCLS_MM = $c.stf.getQuery(frame.srcUrl, "BAS_ACNTCLS_MM");
    let vIWRTRPT_KIND_CD = $c.stf.getQuery(frame.srcUrl, "WRTRPT_KIND_CD");
    scwin.vDepCd = $c.stf.getQuery(frame.srcUrl, "DEP_CD");
    txb_BAS_ACNTCLS_MM.setValue($c.stf.getQuery(frame.srcUrl, "BAS_ACNTCLS_MM"));
    txb_WRTRPT_KIND_CD.setValue($c.stf.getQuery(frame.srcUrl, "WRTRPT_KIND_CD"));
    txb_BAS_YY.setValue($c.stf.getQuery(frame.srcUrl, "BAS_YY"));
    txb_BAS_ACNTCLS_MM_YY.setValue($c.stf.getQuery(frame.srcUrl, "BAS_ACNTCLS_MM_YY"));
    txb_WRTRPT_KIND_CDNM.setValue($c.stf.getQuery(frame.srcUrl, "WRTRPT_KIND_CDNM"));
    txb_DEPT.setValue($c.stf.getQuery(frame.srcUrl, "DEP_CDNM"));
    edt_SCHDL_DD.setValue($c.stf.getQuery(frame.srcUrl, "WRTRPT_SUBMIT_SCHDL_DD"));
    scwin.vIMKT_ID = $c.stf.getQuery(frame.srcUrl, "MKT_ID");
    scwin.gBondYn = 'N`';
    txb_MKT_CD.setValue(scwin.vIMKT_ID);
    if (scwin.vIMKT_ID === '1') {
        txb_MKT_NM.setValue('유가');
    } else if (scwin.vIMKT_ID === '2') {
        txb_MKT_NM.setValue('코스닥');
    } else if (scwin.vIMKT_ID === '4') {
        txb_MKT_NM.setValue('채권');
        scwin.gBondYn = 'Y';
    }
    if (scwin.gBondYn === 'Y') {
        $c.cm.setColumnProp(grd_Grid, "DEL_YN", "Show", false);
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnClick = function(row, colid) {
    // fn_read(grd_Grid, row, colid);

};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        await scwin.read(grd_Grid, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26601.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26601.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert('trs_Save.OnFail() :' + trs_Save.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26601.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26601.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_ToExcel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ToExcel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF26601.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "제출현황목록", type: "2"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26601.btn_ToExcel_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        await scwin.openNew();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26601.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        if (scwin.gBondYn === 'Y') {
            $c.cm.IsurcdSearchBond(txb_ISUR_CD, txb_COM_NM);
        } else {
            $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26601.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26601.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
        Grd_com_isur.style.left = "92px";
        Grd_com_isur.style.top = "75px";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26601.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26601.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26601.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26601.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26601.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26601.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26601.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26601.MxDataSet_com_isur_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readDel
 * @description 작업해야함
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readDel = async function(GridID, row) {
    // 작업해야함
    let objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    let vIBAS_YY = objDataID.getCellData(row, "BAS_YY");
    let vIBAS_ACNTCLS_MM = objDataID.getCellData(row, "BAS_ACNTCLS_MM");
    let vIWRTRPT_KIND_CD = objDataID.getCellData(row, "WRTRPT_KIND_CD");
    let vIISUR_CD = objDataID.getCellData(row, "ISUR_CD");
    let vIACP_YN = cmb_ACP_YN.getValue();
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     BAS_YY : vIBAS_YY,
    //     BAS_ACNTCLS_MM : vIBAS_ACNTCLS_MM,
    //     WRTRPT_KIND_CD : vIWRTRPT_KIND_CD,
    //     MKT_ID : scwin.vIMKT_ID,
    //     ACP_YN : vIACP_YN,
    //     ISUR_CD : vIISUR_CD
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/SubmitStatus.do",
        ref : "dts_Grid",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    let vIBAS_YY = txb_BAS_YY.getValue();
    let vIBAS_ACNTCLS_MM = txb_BAS_ACNTCLS_MM.getValue();
    let vIWRTRPT_KIND_CD = txb_WRTRPT_KIND_CD.getValue();
    let vIISUR_CD = txb_ISUR_CD.getValue();
    let vIACP_YN = cmb_ACP_YN.getValue();
    url += "&BAS_YY=" + vIBAS_YY;
    url += "&BAS_ACNTCLS_MM=" + vIBAS_ACNTCLS_MM;
    url += "&WRTRPT_KIND_CD=" + vIWRTRPT_KIND_CD;
    url += "&ISUR_CD=" + vIISUR_CD;
    url += "&ACP_YN=" + vIACP_YN;
    url += "&MKT_ID=" + scwin.vIMKT_ID;
    url += "&DEP_CD=" + scwin.vDepCd;
    url += "&BOND_YN=" + scwin.gBondYn;
    url += "&SCREN_ID=" + 'ULDSTF26601.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/SubmitStatus.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openNew
 * @description open New 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openNew = async function() {
    const options = {
        id: "ULDSTF26605",
        title: "신규",
        type: "browserPopup",
        width: "480px",
        height: 210 + 40,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/dsclsrch/ULDSTF26605.gfm", options);
};

/**
 * @method
 * @name read
 * @description read 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function(GridID, row, colid) {
    if (row < 1) return;
    let objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    // DEL_YN
    if (colid === "DEL_YN") {
        // 수정용 화면.
        if (confirm("삭제를 하시겟습니까?")) {
            await scwin.readDel(GridID, row);
        }
    } else if (colid === "COM_ABBRV") {
        scwin.gIsurCd = dts_Grid.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid === "SUBMIT_YN") {
        const AcptNo = objDataID.getCellData(row, "ACPT_NO");
        if (AcptNo === "") {
            if (scwin.vIMKT_ID === '2') {
                // 코스닥일때만 적용
                // 미제출일때만 링크한다.
                await scwin.openNSubmitMgt(objDataID.getCellData(row, "ISUR_CD"));
            }
        }
    }
};

/**
 * @method
 * @name openNSubmitMgt
 * @description open NSubmit Mgt 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openNSubmitMgt = async function(obj) {
    let url = "/dsclsrch/ULDSTF26610.gfm?ISUR_CD=" + obj;
    const winTitle = "정기보고서 미제출법인 관리";
    await $c.frame.CreateDialogFrame("NSUBMITINFO1", url, winTitle, 50, 100, 700, 330, "window");
};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    /*
    showObj(txb_BAS_ACNTCLS_MM, false);
    showObj(txb_WRTRPT_KIND_CD, false);
    //showObj(txb_ISUR_CD, false);
    showObj(txb_MKT_CD, false);
     */
    panel_debug.hide();
};
